@page{margin:0}body{margin:0;font-family:DejaVu Sans,sans-serif;color:#342619}.certificate{height:210mm;box-sizing:border-box;padding:18mm;border:10px solid #b99150;text-align:center;background:#fffdf8}.inner{height:100%;box-sizing:border-box;border:2px solid #d9bf8d;padding:16mm 20mm}.brand{font-size:14px;letter-spacing:3px;color:#8b6934;font-weight:bold}.title{font-family:DejaVu Serif,serif;font-size:38px;margin:12mm 0 5mm}.intro{font-size:15px;color:#695c50}.name{font-family:DejaVu Serif,serif;font-size:30px;font-weight:bold;margin:7mm 0 3mm;color:#8b6934;border-bottom:1px solid #d9bf8d;padding-bottom:4mm}.program{font-size:21px;font-weight:bold;margin:5mm auto;max-width:220mm}.details{font-size:13px;line-height:1.7;color:#695c50}.footer{margin-top:14mm;display:table;width:100%}.footer>div{display:table-cell;width:50%;vertical-align:bottom}.line{width:55mm;margin:0 auto 3mm;border-top:1px solid #342619}.serial{margin-top:8mm;font-size:10px;color:#7a6d61}
